-- 테스트 상세 이미지 삭제 (업체 미연결 0번 / 테스트 업체 이미지)
DELETE FROM `partner_files` WHERE `partner_idx` = 0 OR `partner_idx` IN (5, 6) OR `partner_idx` NOT IN (SELECT `idx` FROM `partner`);

-- 상품 브랜드에 맞게 제조기업 재연결
UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'NONGSHIM' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%신라면%' OR `product_name` LIKE '%농심%';
UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'Samyang Foods' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%삼양%' OR `product_name` LIKE '%불닭%' OR `product_name` LIKE '%짜짜로니%';
