UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'Dongwon F&B' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%동원%';
UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'Daesang Chung Jung One' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%종가%' OR `product_name` LIKE '%청정원%';
UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'OTTOGI' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%오뚜기%';
UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'ORION' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%오리온%' OR `product_name` LIKE '%초코파이%' OR `product_name` LIKE '%꼬북칩%';
UPDATE `product` SET `partner_idx` = (SELECT `idx` FROM `partner` WHERE `partner_name_en` = 'Binggrae' AND `country` = 'korea' LIMIT 1) WHERE `product_name` LIKE '%빙그레%' OR `product_name` LIKE '%바나나맛우유%' OR `product_name` LIKE '%메로나%';
